1	/**
2	 * The rule language: how rules are written in the interface files
3	 * (events.ts, geometry.ts, color.ts, shape.ts, frames.ts, view.ts,
4	 * shapeView.ts and layout.ts), and the generic vocabulary
5	 * for their expressions. Imports nothing.
6	 *
7	 * Vocabulary files. An interface file x.ts that needs vocabulary of its own
8	 * domain has x.vocab.ts beside it: reference functions and ghost state. It
9	 * re-exports this file and the vocabulary of the files x.ts imports, and
10	 * imports nothing else, so what a rule can mention stays within what its
11	 * interface can see. Tests import the vocabulary of the interface they
12	 * check.
13	 *
14	 * Format. Each rule is a tag, a slug and a one-line headline. Following
15	 * indented lines, when present, give the rule as a TypeScript boolean
16	 * expression: the rule's formal statement. The headline is a gloss on it,
17	 * and where they differ the expression is the rule. A rule with only a
18	 * headline is defined by the test with its ID; the rules of shapeModel.ts
19	 * all have expressions, and the others are to follow. Tests evaluate the
20	 * expressions themselves, compiled from the interface files, rather than
21	 * restating them. The tags say whose obligation a rule is and when it must
22	 * hold:
23	 * - @requires: the caller's, on entry to a call. A rule that uses
24	 *   nested(this) is about the calls the caller makes back into the object
25	 *   during the call, so it is checked on return.
26	 * - @ensures: the implementation's, on return from a call. A rule in an
27	 *   interface's doc holds for calls of that interface's members, its own
28	 *   and those it inherits.
29	 * - @invariant: the implementation's, for one object: true once it is made,
30	 *   after every call, and whenever the object emits an event, so that a
31	 *   listener sees an object whose invariants hold.
32	 * - @valid: which values are legal members of a type. Like finite numbers
33	 *   (below), it holds of every value of the type passed to or returned by
34	 *   an interface. Passing an invalid one is outside the rules; returning one
35	 *   breaks the implementation's obligation. Tests check it wherever an
36	 *   implementation returns values of the type, or, for a type that only
37	 *   flows into implementations, on the values the tests make.
38	 * - @abstract: the implementation's, stated for an interface that others
39	 *   extend, but testable only for each of them. Each interface that
40	 *   extends it, directly or through others, names the rule of its own that
41	 *   makes it exact, with a line "@refines <abstract rule's ID>  <own slug>",
42	 *   and that rule is tested. An @refines in an ancestor covers the
43	 *   interfaces below it. npm run catalog checks all of this.
44	 * - @budget: the implementation's, a limit on time or memory. Its
45	 *   expression names a complexity class (Complexity below), which has its
46	 *   usual mathematical meaning, and a measurement that stands in for it. A
47	 *   bench script (bench.ts) makes the measurement and reports the result,
48	 *   labeled with the rule's ID. Passing the measurement with an algorithm
49	 *   outside the class still breaks the rule.
50	 * - @deferred: the implementation's, for behavior that can't be checked
51	 *   until a feature exists. Two indented lines follow it instead of an
52	 *   expression: "when:" names what must exist first, and "how:" says how
53	 *   it will be checked then. When a test with its ID is written, the rule
54	 *   becomes @ensures. npm run catalog checks both.
55	 *
56	 * IDs. A rule's ID follows its location: Interface.slug for a rule in an
57	 * interface's doc, Interface.member.slug for one in a member's doc. The test
58	 * that checks a rule has the rule's ID as its name. A rule inherited from
59	 * another interface keeps its original ID. A rule in a file's header
60	 * applies to the whole file; its ID is the file's name without .ts, then
61	 * the slug, such as frames.complete.
62	 *
63	 * Outside the rules. When a caller breaks a @requires rule, or passes a value
64	 * that doesn't match its static type, behavior is unspecified. An
65	 * implementation may throw, and declares what it does under
66	 * AdditionalSemantics.
67	 *
68	 * Numbers are finite. Every number in a value passed to or returned by an
69	 * interface, including inside its fields, is finite (allFinite below).
70	 * Passing a non-finite number is outside the rules, like a value of the
71	 * wrong type.
72	 *
73	 * In a rule expression:
74	 * - Method parameters are in scope by name, `this` is the object under test
75	 *   and `result` is the method's return value.
76	 * - A rule written as an arrow function, such as `(p: Point) => …`, holds for
77	 *   every value of its parameters. Tests generate those values.
78	 * - old(e) is the value of e just before the call, and atEvent(i, e) its
79	 *   value when the call emitted its i-th event.
80	 * - history(o) is the calls made on o from outside it, ending with the call
81	 *   the rule is about. It is the only state a rule may use beyond what the
82	 *   interfaces expose: what an observer of o records, calls and the events
83	 *   emitted during them. Vocabulary defines everything else a rule needs
84	 *   from it.
85	 * - The functions below and in the interface file's vocabulary may be used. They are reference
86	 *   definitions, kept deliberately simple.
87	 * - Rules mean exact arithmetic when they compare an implementation with the
88	 *   reference functions. An implementation may compute in a different
89	 *   order and round differently. Tests use inputs on which floating-point
90	 *   arithmetic is exact, or skip cases within rounding distance of a tie.
91	 *   Rules that relate an object's own methods to each other, such as
92	 *   Shape's implies-box rules, hold as actually computed, with no allowance.
93	 *
94	 * @module
95	 */
96	
97	/** The value of e just before the call. Rewritten by the rule tooling; never called. */
98	export declare function old<T>(e: T): T;
99	
100	/**
101	 * The value of e when the call emitted its i-th event (from 0), or
102	 * undefined if it emitted fewer. Rewritten by the rule tooling; never
103	 * called.
104	 */
105	export declare function atEvent<T>(i: number, e: T): T | undefined;
106	
107	/** An event emitted during a call: its name, and the arguments its listeners got. */
108	export interface Emitted {
109	  readonly event: string;
110	  readonly args: readonly unknown[];
111	}
112	
113	/** One call made on an object, as seen from outside it. */
114	export interface Call {
115	  /** The member called, such as "add"; a member of a member is "local.enqueue". Reading a property is a call. */
116	  readonly member: string;
117	  /** The arguments, as they were when the call was made. */
118	  readonly args: readonly unknown[];
119	  /** The arguments the caller passed, the same values, as they are now; where they differ from args, someone changed them after the call. */
120	  readonly given: readonly unknown[];
121	  /** The return value, as it was on return; for an asynchronous call, the value its promise settled with. */
122	  readonly result: unknown;
123	  /** The events the object emitted during the call, in order. */
124	  readonly emitted: readonly Emitted[];
125	  /** The calls made on the object during this one, such as by a listener or a visit callback, in order. */
126	  readonly nested: readonly Call[];
127	}
128	
